INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1160, 19, 'activity', 'owner', NULL, 'title', '2026-10-19 02:31:04.524354+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "Language switch flashes on Android: the spinner unmounts, a target-language flash, then a blank purple page"}, "from": {"value": "#141 Language switch flashes on Android: the spinner unmounts, a target-language flash, then a blank purple page"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (1161, 19, 'activity', 'owner', NULL, 'description', '2026-10-19 02:31:04.524354+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "OWNER REPORT 2026-10-18 (evening), Android-only (the iPhone behaves exactly as the owner wants): switching language in either direction (en to ar and ar to en) on the 3T shows, in order: the loading spinner; the spinner DISAPPEARING for a few milliseconds; a FLASH of the schedule itself - the owner read the TARGET language and saw the target layout switch during the flash when going ar to en; then a full-screen BLANK PURPLE page with no spinner for about half a second; then the full app. EXPECTED, the owner''s word: exactly the iPhone''s behavior - the spinner shows immediately on the language change and NEVER unmounts, moves or disables until the app is fully ready (all measurements done, the UI and layout measured), and only then the app appears - no flash of intermediate state, no blank page. THE TICKET: investigate the Android render and mount sequence through a language switch (what unmounts the spinner, what renders the schedule mid-switch, what renders the blank purple page, why iOS does not), then fix to the iPhone''s contract; red-first where a guard fits; both directions, both schedules; En byte-identical when not switching. Acceptance: the owner''s read of a language switch on the 3T\n\nStatus note: 2026-10-18, OWNER REPORT"}}', NULL);
