INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2013, 239, 'comment', 'owner', 'Cleanup hook added 2026-10-19 by the owner''s order, folded from row 233: when a published expo-widgets release carries the device-locale global, this row also deletes the local patch''s locale hunks and moves the ledger entry to shipped, then closes. One row carries the whole life of the PR.', NULL, '2026-10-19 09:16:01.372499+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
