INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2525, 276, 'comment', 'owner', 'Plan written and linked: the owner''s Design 1 fixed on the dots-bottom line, nine varied arrangements after it (mirrored corner pairs, a floating pill, an integrated capsule, edge rails, a segmented track, a wide aperture, a corner stack). Two steps: the switcher build, then the device shots. Nothing merges; the branch dies after the screenshots.', NULL, '2026-10-20 03:54:20.62625+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
