INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2536, 276, 'comment', 'owner', 'Step 1 landed on the branch: the ten arrangements and the debug-only switcher are in at 2.1.34, validate green, and nothing shipped moves with the gate off in every normal build. Left: the ten screenshots from the phone (step 2), with the switcher build carrying EXPO_PUBLIC_DESIGN_SWITCHER=1.', NULL, '2026-10-20 04:11:22.215101+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
