INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2547, 271, 'comment', 'owner', 'Step 3: the branch diff read end to end names only the orientation-gate plugin, its test, the version and config files, the collision allowlist and the board snapshot, so no phone-tuned layout value moved and no phone pixel changes. The plan doc carries the closing revision with Step 2b''s recorded limitation and the final commit list.', NULL, '2026-10-20 05:13:32.681868+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
