INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2594, 276, 'comment', 'owner', 'Delivered: all ten designs screenshotted on the iPhone XS and attached in order (design-01.png to design-10.png), each with its one-liner; the vision pass verified the badge order D1/10 to D10/10 against the pixels. Nothing merged: the prototype branch lane/276 is deleted, uat stays byte-identical at 2.1.33. Both reviewers passed the protocol audit. Note for the pick: the XS currently carries the mock prototype build itself, so the designs can also be seen cycling live on the phone.', NULL, '2026-10-20 05:22:13.245342+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
