INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (2601, 271, 'comment', 'owner', 'Closed by the owner''s final ruling (comment 2585): Option A cancelled completely, the landscape-span gate never merged - uat carries none of it, and the branch is deleted with all four commits. The Duo''s answer is Option B on row 280. The row keeps the full record Option B builds on: the measured spanning geometry, the fence readings, the clamp identity, and the two refused re-ask routes for a live unfold.', NULL, '2026-10-20 05:27:58.916949+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, 2585, '{}', NULL);
