INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3100, 294, 'comment', 'owner', 'Owner order, dictated 2026-10-21: the rule is universal - any text at any opacity under 1 shows the overlap compounding, in every language, and the fix treats all text as one whole. No per-language and no per-platform treatment; English staying visually clean is not a reason to keep opacity anywhere. Consequence for the plan: the three deferred veil fades (prayer rows, ago badge, info box) convert with no exceptions, and the veil-merge colour stops being the owner''s question - engineering rules the mechanism (a covering veil over solid text, or an ink tween to the surface), never translucent text.', NULL, '2026-10-21 14:18:33.307081+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3101, 294, 'activity', 'owner', NULL, 'field', '2026-10-21 14:18:37.628899+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{"to": {"value": "the owner''s phone read of the lane/294 mock build on the 3T under Arabic (and the iPhone): the even-ink verdict on overlapping glyphs, and the corner-deviation read on the gradient dim solids. The build itself awaits the owner''s word - agent builds and installs on the 3T, or the owner builds. The veil mechanism is now engineering''s to rule, per the 2026-10-21 order."}, "subject": {"id": 3, "value": "Waiting on"}}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3102, 294, 'comment', 'owner', 'Prior art researched on the owner''s order and folded into the plan doc: the defect is Android''s own open bug (AOSP 565711357, filed 2026-09-24, assigned, unfixed - same seams at Arabic cursive joins, same expected result as this ticket), the W3C ruled in 2020 that opacity applies to a whole text run, never per glyph (CSS Color 4 amended with an Arabic example), WebKit/iOS already comply while Chromium and Gecko still compound, and the only redress available to a per-glyph stack is solid pre-blended ink - which is what Android''s own theme text colours and Material''s shipped tokens do. Solid ink everywhere stands confirmed as the one road under the no-platform-split order.', NULL, '2026-10-21 14:21:46.668457+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3103, 294, 'comment', 'owner', 'Owner order, dictated 2026-10-21: the AOSP and Chromium bugs are not watched - no upstream rows, no tracking. The solid-ink approach is confirmed and execution is green-lit: Steps 2 and 3 proceed now, the phone read follows on a built mock, the merge after the read. The veil mechanism stays engineering''s to rule per the earlier order.', NULL, '2026-10-21 14:24:59.019737+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
