INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3180, 322, 'comment', 'owner', 'Reopened on the owner''s order (dictated 2026-10-24, read on the 2.4.22 production mock build, both platforms): the compass bottom sheet still shows doubled instruction text - the bright ''follow below instructions'' line with dark text stacked above it, on the iPhone as well as Android. The dark line reads as the hidden or opacity text that should never paint, likely the waiting line or the wave line showing through the crossfade''s resting state. The single-instruction-line acceptance criterion is unmet; the row returns to Backlog for a fresh plan step. Everything else in the pass stood approved.', NULL, '2026-10-24 19:55:37.551303+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
