INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3223, 327, 'comment', 'owner', 'Plan written and grilled: doc T-327 (id 35), eight steps, 22 points, six of them device sessions on the 3T and two XS controls. The ticket''s Lane (2) and Ticket number fields were empty on pickup and are now written; the MCP read returns fieldValues empty for every ticket, so the lead verifies them at the phase boundary.', NULL, '2026-10-24 20:13:47.818383+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
