INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3311, 327, 'comment', 'owner', 'Owner verdict (dictated 2026-10-25, on the 2.4.28 production builds): the 3T lags heavily - confirmed on glass, not the earlier mistake. The owner''s theory: the prayer rows'' conversion from one shared opacity to per-row shaded colours may cost the animation (or a Reanimated upgrade is due). Deferred to a dedicated deep-dive AFTER the release, per the owner''s order; the S23 gets the same 2.4.28 APK now and the owner reads performance on it - if the S23 lags too, the issue is code, not the 2017 device, and it becomes release-blocking.', NULL, '2026-10-25 04:16:42.934893+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
