INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3431, 327, 'comment', 'owner', 'Re-planned on the owner''s run order (2026-10-25): the doc now runs the instrument first - a same-tap SF present-timestamp read beside the video (Step 9), the tip''s separated verdict (10), the baseline-era anchor dated A/B/A (11), then the widened bisect or the degradation record (12), cause and fix (13), post-fix proof (14), the XS after-picture (15) and close-out (16). Step 2 (the XS before-picture, T-329) stays open and reconciled; the done steps keep their records. Estimate re-pointed to 43; grilled, four findings answered in the doc.', NULL, '2026-10-25 08:03:00.172391+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3437, 347, 'comment', 'owner', 'Merged to uat at 2.4.43 (c2441e8) with the audit passed: the README now names every user-facing feature the history records, every claim holds against the current build, and the source list sits above. Parked for the owner''s approval to close.', NULL, '2026-10-25 08:30:11.673571+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
