INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3479, 348, 'comment', 'owner', 'Blind review of 3b0e7ab7 (c2441e89..3b0e7ab7), verified by command in the lane3 worktree.

