INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3551, 346, 'comment', 'owner', 'Audit clean: both reviewers, plan-conformance and blind, returned no findings, and yarn validate is green on the merged tree (234 suites). Merged to local uat as 2.5.2, renumbered above uat''s 2.5.1 (lane3/T-348''s What''s New minor) under the standing collision ruling; this lane''s 2.4.45 and 2.4.46 stamps carry no twin on any lane and stand below the 2.5 minor in uat''s history.', NULL, '2026-10-25 14:28:03.942346+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3553, 346, 'comment', 'owner', 'All three steps are done: the spacing gate with the Thai byte, the one-line badge with its six-locale suite, and the transcribed device reads on the 3T (standing in for the unattached S23) and the XS. Merged to uat at 2.5.2 with the audit clean; parked for the owner''s approval to close per run order 2026-10-25.', NULL, '2026-10-25 14:28:04.012861+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3541, 368, 'comment', 'owner', 'Planned. The plan doc (T-368) pins the reviewed pair - the FINISHED STORE builds at 2.4.39, Android AAB build 11 and iOS IPA build 74, both from git 340bd90e - across five steps: pin, download and identify, measure both phones without displacing anything, smoke the exact binary on the sanctioned emulator, and table the owner decisions with the verdict.', NULL, '2026-10-25 14:18:17.027179+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
