INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3632, 374, 'comment', 'owner', 'The owner picked final-05 (round 10) - execution started on a landing branch: the picked palette lands as the design token (shared/design.ts, the one-dim system), the prototype scaffolding (all round galleries, palettes, generators, the glow and star components and their assets) leaves the tree, the prayer-name text shadow is struck per owner order, and the label and dim ink assertions now read the token instead of literals. Validation green before the commit; the production builds for both platforms follow locally, then the 3T floor proof for the T-327 interplay.', NULL, '2026-10-26 06:09:47.214247+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
