INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3635, 374, 'comment', 'owner', 'Audit complete and merged to uat (575a4a8e over 68376ad1). Two independent reviews - one blind on the diff alone, one against the ticket''s acceptance - plus the lead''s own pass, all findings fixed in the second commit: the time-ago chip joins the one dim ink, the token''s per-surface forks collapse, the overlay label returns to its shipped out-of-scope ink, the dead text.secondary role leaves, the gradient renders its four-stop ramp unconditionally, and a new one-dim sweep suite pins every dimmed surface to the token and the hand-frozen palette itself. Every text on the screen carries alpha exactly 1, enforced by the textInk sweep. Validation green through the merge and push: 235 suites, 6035 tests, 100% coverage. Production builds for the OnePlus 3T and the iPhone XS follow locally now; the owner tests both phones, and on approval T-374 and T-327 close together.', NULL, '2026-10-26 06:42:36.621961+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3636, 374, 'comment', 'owner', 'Both production builds delivered locally from uat 575a4a8e (version 2.7.1, real API, no EAS): the Android release APK built and verified through build-prod (badging, owner certificate, Hermes bundle carrying the key) and installed on the OnePlus 3T for User 0 alone with its data preserved; the iOS Release build signed with the owner''s development certificate and installed on the iPhone XS. Both apps launched. The owner tests both phones now; on approval the 3T''s 30fps floor proof runs on a gate-ON build as T-327''s evidence, then both tickets close together.', NULL, '2026-10-26 07:04:16.202399+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
