INSERT INTO public.issue_activity (id, issue_id, kind, actor_name, body, action, created_at, actor_user_id, initiative_id, reply_to_id, payload, edited_at) VALUES (3638, 374, 'comment', 'owner', 'Closed on the owner''s verdict (2026-10-26): the picked design is landed, audited, merged to uat at 2.7.1 and confirmed by the owner on the 3T''s production build. The owner rules the redesign introduced no regression; the 3T''s frame drops predate it and stay T-327''s own subject, which returns to Backlog. Two follow-ups ship next: the version label returns to the What''s New modal and the gradient''s source slides toward the bottom mid-right.', NULL, '2026-10-26 07:23:36.174799+00', 'DFppJIU20ig1j5gFRYQIe541IkO7Itfp', NULL, NULL, '{}', NULL);
